import {
  createTerminalInstance,
  disposeTerminalInstance,
  type TerminalInstance,
} from "./terminalInstanceFactory";
import { attachScheduledOutputSubscription, MAX_PENDING_OUTPUT_CHARS } from "./terminalOutputScheduler";
import {
  applyTerminalSettings,
  type EffectiveTerminalSettings,
} from "./terminalSettings";
import type { TerminalSession } from "./types";

export type { TerminalInstance };
export { MAX_PENDING_OUTPUT_CHARS };

export const DEFAULT_WARM_CACHE_LIMIT = 2;

type SpawnGeneration = {
  generation: number;
  activeCount: number;
};

class TerminalHostManager {
  private instances = new Map<string, TerminalInstance>();
  private pendingSpawns = new Map<string, Promise<TerminalInstance>>();
  private spawnGenerations = new Map<string, SpawnGeneration>();
  private visibleRefCounts = new Map<string, number>();
  private inactiveLruSessionIds: string[] = [];
  private warmCacheLimit = DEFAULT_WARM_CACHE_LIMIT;

  setWarmCacheLimit(limit: number): void {
    this.warmCacheLimit = Math.max(0, limit);
    this.evictInactiveIfNeeded();
  }

  getWarmCacheLimit(): number {
    return this.warmCacheLimit;
  }

  isSessionVisible(sessionId: string): boolean {
    return (this.visibleRefCounts.get(sessionId) ?? 0) > 0;
  }

  registerVisible(sessionId: string): () => void {
    const current = this.visibleRefCounts.get(sessionId) ?? 0;
    this.visibleRefCounts.set(sessionId, current + 1);
    if (current === 0) {
      this.markSessionVisible(sessionId);
    }
    let unregistered = false;
    return () => {
      if (unregistered) return;
      unregistered = true;
      const count = (this.visibleRefCounts.get(sessionId) ?? 1) - 1;
      if (count <= 0) {
        this.visibleRefCounts.delete(sessionId);
        this.markSessionInactive(sessionId);
      } else {
        this.visibleRefCounts.set(sessionId, count);
      }
    };
  }

  setVisible(sessionId: string, visible: boolean): void {
    if (visible) {
      const current = this.visibleRefCounts.get(sessionId) ?? 0;
      this.visibleRefCounts.set(sessionId, Math.max(1, current));
      this.markSessionVisible(sessionId);
    } else {
      this.visibleRefCounts.delete(sessionId);
      this.markSessionInactive(sessionId);
    }
  }

  private markSessionVisible(sessionId: string): void {
    this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== sessionId);
    const inst = this.instances.get(sessionId);
    if (inst) {
      if (!inst.unsubscribeOutput) {
        inst.terminal.reset();
        if (inst.session.backendSessionId) {
          inst.unsubscribeOutput = attachScheduledOutputSubscription(inst.session.backendSessionId, inst.terminal);
        }
      }
    }
  }

  private markSessionInactive(sessionId: string): void {
    const inst = this.instances.get(sessionId);
    if (inst) {
      inst.unsubscribeOutput?.();
      inst.unsubscribeOutput = undefined;
    }
    this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== sessionId);
    this.inactiveLruSessionIds.push(sessionId);
    this.evictInactiveIfNeeded();
  }

  private evictInactiveIfNeeded(): void {
    while (this.inactiveLruSessionIds.length > this.warmCacheLimit) {
      const oldestSessionId = this.inactiveLruSessionIds.shift();
      if (!oldestSessionId) break;
      this.disposeFrontendInstance(oldestSessionId);
    }
  }

  private disposeFrontendInstance(sessionId: string): void {
    const inst = this.instances.get(sessionId);
    if (inst) {
      this.instances.delete(sessionId);
      disposeTerminalInstance(inst);
    }
  }

  getInstance(sessionId: string): TerminalInstance | undefined {
    return this.instances.get(sessionId);
  }

  async getOrCreate(
    session: TerminalSession,
    active: boolean,
    onBell?: () => void,
    onTitleChange?: (title: string) => void,
  ): Promise<TerminalInstance> {
    const isVisible = this.isSessionVisible(session.id);
    const existing = this.instances.get(session.id);
    if (existing) {
      existing.session = session;
      existing.active = active;
      existing.onBell = onBell;
      existing.onTitleChange = onTitleChange;

      if (isVisible) {
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        if (!existing.unsubscribeOutput) {
          existing.terminal.reset();
          if (session.backendSessionId) {
            existing.unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, existing.terminal);
          }
        }
      } else {
        if (existing.unsubscribeOutput) {
          existing.unsubscribeOutput();
          existing.unsubscribeOutput = undefined;
        }
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        this.inactiveLruSessionIds.push(session.id);
        this.evictInactiveIfNeeded();
      }
      return existing;
    }

    const pending = this.pendingSpawns.get(session.id);
    if (pending) return pending;

    const currentGen = this.spawnGenerations.get(session.id);
    const generation = (currentGen ? currentGen.generation : 0) + 1;
    const activeCount = (currentGen ? currentGen.activeCount : 0) + 1;
    this.spawnGenerations.set(session.id, { generation, activeCount });

    const spawnPromise = createTerminalInstance({
      session,
      active,
      isVisible: this.isSessionVisible(session.id),
      onBell,
      onTitleChange,
      getInstance: (id) => this.instances.get(id),
    });
    this.pendingSpawns.set(session.id, spawnPromise);

    try {
      const instance = await spawnPromise;
      if (this.spawnGenerations.get(session.id)?.generation !== generation) {
        disposeTerminalInstance(instance);
        return instance;
      }

      this.instances.set(session.id, instance);

      const stillVisible = this.isSessionVisible(session.id);
      if (stillVisible) {
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        if (!instance.unsubscribeOutput && session.backendSessionId) {
          instance.unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, instance.terminal);
        }
      } else {
        if (instance.unsubscribeOutput) {
          instance.unsubscribeOutput();
          instance.unsubscribeOutput = undefined;
        }
        this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== session.id);
        this.inactiveLruSessionIds.push(session.id);
        this.evictInactiveIfNeeded();
      }
      return instance;
    } finally {
      const tracking = this.spawnGenerations.get(session.id);
      if (tracking) {
        tracking.activeCount -= 1;
        if (tracking.activeCount <= 0) {
          this.spawnGenerations.delete(session.id);
        }
      }
      if (this.pendingSpawns.get(session.id) === spawnPromise) {
        this.pendingSpawns.delete(session.id);
      }
    }
  }

  updateSession(sessionId: string, session: TerminalSession) {
    const inst = this.instances.get(sessionId);
    if (inst) {
      const prevBackendId = inst.session.backendSessionId;
      inst.session = session;
      const isVisible = this.isSessionVisible(sessionId);
      if (isVisible) {
        if (session.backendSessionId !== prevBackendId) {
          inst.unsubscribeOutput?.();
          inst.unsubscribeOutput = undefined;
          if (session.backendSessionId) {
            inst.unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, inst.terminal);
          }
        }
      } else {
        if (inst.unsubscribeOutput) {
          inst.unsubscribeOutput();
          inst.unsubscribeOutput = undefined;
        }
      }
    }
  }

  applyInstanceSettings(sessionId: string, settings: EffectiveTerminalSettings) {
    const inst = this.instances.get(sessionId);
    if (inst) {
      applyTerminalSettings(inst.terminal, settings);
      if (inst.element.clientWidth > 0 && inst.element.clientHeight > 0) {
        inst.fitAddon.fit();
      }
    }
  }

  applySettings(settings: EffectiveTerminalSettings) {
    for (const inst of this.instances.values()) {
      applyTerminalSettings(inst.terminal, settings);
      if (inst.element.clientWidth > 0 && inst.element.clientHeight > 0) {
        inst.fitAddon.fit();
      }
    }
  }

  destroy(sessionId: string) {
    const tracking = this.spawnGenerations.get(sessionId);
    if (tracking) {
      tracking.generation += 1;
    }
    this.visibleRefCounts.delete(sessionId);
    this.inactiveLruSessionIds = this.inactiveLruSessionIds.filter((id) => id !== sessionId);
    this.pendingSpawns.delete(sessionId);
    this.disposeFrontendInstance(sessionId);
  }
}

export const terminalHostManager = new TerminalHostManager();

import type { FitAddon } from "@xterm/addon-fit";
import type { SearchAddon } from "@xterm/addon-search";
import type { Terminal } from "@xterm/xterm";

import { isTauriRuntime, resizeTerminal, writeTerminal } from "./tauri";
import { attachScheduledOutputSubscription } from "./terminalOutputScheduler";
import { attachWebglRenderer, loadTerminalAssets } from "./terminalRenderer";
import {
  FALLBACK_PREFERENCES,
  fetchCachedNativePreferences,
  loadTerminalSettings,
  resolveTerminalSettings,
} from "./terminalSettings";
import type { TerminalSession } from "./types";

export type TerminalInstance = {
  element: HTMLDivElement;
  terminal: Terminal;
  fitAddon: FitAddon;
  searchAddon: SearchAddon;
  disposeWebgl: () => void;
  resizeObserver: ResizeObserver;
  disposables: Array<() => void>;
  session: TerminalSession;
  active: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
  unsubscribeOutput?: () => void;
};

export type CreateTerminalInstanceOptions = {
  session: TerminalSession;
  active: boolean;
  isVisible: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
  getInstance: (sessionId: string) => TerminalInstance | undefined;
};

export function disposeTerminalInstance(inst: TerminalInstance): void {
  inst.resizeObserver.disconnect();
  inst.unsubscribeOutput?.();
  inst.unsubscribeOutput = undefined;
  for (const d of inst.disposables) d();
  inst.searchAddon.dispose();
  inst.disposeWebgl();
  inst.terminal.dispose();
  inst.element.remove();
}

export async function createTerminalInstance({
  session,
  active,
  isVisible,
  onBell,
  onTitleChange,
  getInstance,
}: CreateTerminalInstanceOptions): Promise<TerminalInstance> {
  const hostElement = document.createElement("div");
  hostElement.className = "terminal-host h-full w-full bg-terminal";
  hostElement.setAttribute("aria-label", `Terminal in ${session.cwd}`);
  Object.assign(hostElement.style, {
    position: "absolute",
    inset: "0px",
    width: "100%",
    height: "100%",
    minWidth: "0px",
    minHeight: "0px",
    overflow: "hidden",
  });

  const [latestNativePrefs, { Terminal: TerminalConstructor, FitAddon: FitAddonConstructor, Unicode11Addon, SearchAddon: SearchAddonConstructor }] =
    await Promise.all([
      Promise.race([
        fetchCachedNativePreferences(),
        new Promise<typeof FALLBACK_PREFERENCES>((resolve) =>
          setTimeout(() => resolve(FALLBACK_PREFERENCES), 200),
        ),
      ]),
      loadTerminalAssets(),
    ]);

  const finalSettings = resolveTerminalSettings(loadTerminalSettings(), latestNativePrefs);

  const terminal = new TerminalConstructor({
    allowProposedApi: false,
    customGlyphs: false,
    convertEol: true,
    cursorBlink: true,
    cursorStyle: finalSettings.cursorStyle ?? "block",
    fontFamily: finalSettings.fontFamily,
    fontSize: finalSettings.fontSize,
    lineHeight: 1.0,
    letterSpacing: 0,
    macOptionIsMeta: finalSettings.macosOptionAsAlt,
    scrollback: finalSettings.scrollback,
    theme: finalSettings.theme,
  });
  const fitAddon = new FitAddonConstructor();
  terminal.loadAddon(fitAddon);
  const searchAddon = new SearchAddonConstructor();
  terminal.loadAddon(searchAddon);
  if (Unicode11Addon) {
    try {
      const unicode11Addon = new Unicode11Addon();
      terminal.loadAddon(unicode11Addon);
      terminal.unicode.activeVersion = "11";
    } catch {
    }
  }
  terminal.open(hostElement);

  let disposeWebgl: () => void = () => undefined;
  void attachWebglRenderer(terminal).then((dispose) => {
    disposeWebgl = dispose;
  });

  let resizeFrame = 0;
  const resize = () => {
    cancelAnimationFrame(resizeFrame);
    resizeFrame = requestAnimationFrame(() => {
      if (hostElement.clientWidth === 0 || hostElement.clientHeight === 0) return;
      fitAddon.fit();
      const backendSessionId = session.backendSessionId;
      if (!backendSessionId) return;
      void resizeTerminal({ sessionId: backendSessionId, cols: terminal.cols, rows: terminal.rows }).catch(() => undefined);
    });
  };

  const resizeObserver = new ResizeObserver(resize);
  resizeObserver.observe(hostElement);

  const disposables: Array<() => void> = [];

  const dataDisposable = terminal.onData((data) => {
    const backendSessionId = session.backendSessionId;
    if (!backendSessionId) return;
    void writeTerminal({ sessionId: backendSessionId, data }).catch(() => undefined);
  });
  disposables.push(() => dataDisposable.dispose());

  const titleDisposable = terminal.onTitleChange((title) => {
    getInstance(session.id)?.onTitleChange?.(title);
  });
  disposables.push(() => titleDisposable.dispose());

  const bellDisposable = terminal.onBell(() => {
    getInstance(session.id)?.onBell?.();
  });
  disposables.push(() => bellDisposable.dispose());

  const focusTerminal = () => terminal.focus();
  hostElement.addEventListener("pointerdown", focusTerminal);
  disposables.push(() => hostElement.removeEventListener("pointerdown", focusTerminal));

  let unsubscribeOutput: (() => void) | undefined;
  if (isVisible && session.backendSessionId) {
    unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, terminal);
  }

  if (!isTauriRuntime()) {
    terminal.writeln("\x1b[1;32mFerryx\x1b[0m  UI preview");
    terminal.writeln("\x1b[90mLaunch through Tauri to attach the PTY session.\x1b[0m");
    terminal.write("\r\n\x1b[34m~\x1b[0m \x1b[32m❯\x1b[0m ");
  }

  resize();
  if (active) terminal.focus();

  return {
    element: hostElement,
    terminal,
    fitAddon,
    searchAddon,
    disposeWebgl,
    resizeObserver,
    disposables,
    session,
    active,
    onBell,
    onTitleChange,
    unsubscribeOutput,
  };
}

import type { Terminal } from "@xterm/xterm";

import { terminalEventBus } from "./terminalEvents";

export const MAX_PENDING_OUTPUT_CHARS = 128 * 1024;

/**
 * Batches incoming PTY output chunks per terminal renderer at animation-frame cadence.
 *
 * Queue policy:
 * - Chunks received between rAF flushes are held in an ordered per-renderer buffer.
 * - On frame flush, all buffered chunks coalesce into a single `terminal.write` call in original arrival order.
 * - If queued characters reach or exceed `MAX_PENDING_OUTPUT_CHARS` before rAF, the buffer is flushed synchronously
 *   to guarantee memory safety without loss or reordering.
 * - Replay backlog delivered synchronously during `subscribeOutput` is enqueued before subsequent live output.
 * - Teardown (via unlisten or manager destroy) immediately cancels pending rAF callbacks and clears buffered data,
 *   preventing stale or out-of-order writes after session rebinding or instance disposal.
 */
export function attachScheduledOutputSubscription(
  backendSessionId: string,
  terminal: Terminal,
): () => void {
  let outputBuffer: string[] = [];
  let outputBufferChars = 0;
  let outputFrame = 0;

  const flushOutput = () => {
    if (outputFrame !== 0) {
      cancelAnimationFrame(outputFrame);
      outputFrame = 0;
    }
    if (outputBuffer.length === 0) return;
    const coalesced = outputBuffer.length === 1 ? (outputBuffer[0] ?? "") : outputBuffer.join("");
    outputBuffer = [];
    outputBufferChars = 0;
    terminal.write(coalesced);
  };

  const unsubscribe = terminalEventBus.subscribeOutput(backendSessionId, (text) => {
    outputBuffer.push(text);
    outputBufferChars += text.length;

    if (outputBufferChars >= MAX_PENDING_OUTPUT_CHARS) {
      flushOutput();
    } else if (outputFrame === 0) {
      outputFrame = requestAnimationFrame(flushOutput);
    }
  });

  return () => {
    if (outputFrame !== 0) {
      cancelAnimationFrame(outputFrame);
      outputFrame = 0;
    }
    outputBuffer = [];
    outputBufferChars = 0;
    unsubscribe();
  };
}

import { useEffect, useRef, useState } from "react";

import { terminalHostManager } from "../lib/terminalHostManager";
import { useTerminalSettings } from "../lib/terminalSettings";
import type { TerminalSession } from "../lib/types";
import { TerminalSearchOverlay } from "./TerminalSearchOverlay";

type TerminalPaneProps = {
  session: TerminalSession;
  active: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
  searchOpen?: boolean;
  onCloseSearch?: () => void;
};

export function TerminalPane({ session, active, onBell, onTitleChange, searchOpen, onCloseSearch }: TerminalPaneProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [error, setError] = useState<string | null>(null);
  const { settings } = useTerminalSettings();

  useEffect(() => {
    return terminalHostManager.registerVisible(session.id);
  }, [session.id]);

  useEffect(() => {
    terminalHostManager.applyInstanceSettings(session.id, settings);
  }, [session.id, settings]);

  useEffect(() => {
    terminalHostManager.updateSession(session.id, session);
  }, [session]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    let cancelled = false;

    void terminalHostManager
      .getOrCreate(session, active, onBell, onTitleChange)
      .then((instance) => {
        if (cancelled) return;
        if (!container.contains(instance.element)) {
          container.replaceChildren(instance.element);
        }
        if (active) {
          instance.terminal.focus();
        }

        const fontsReady = typeof document !== "undefined" ? document.fonts?.ready : undefined;
        void fontsReady?.then(() => {
          if (!cancelled && instance.element.clientWidth > 0 && instance.element.clientHeight > 0) {
            instance.fitAddon.fit();
          }
        });
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : "Failed to mount terminal");
      });

    return () => {
      cancelled = true;
    };
  }, [session.id]);

  useEffect(() => {
    const instance = terminalHostManager.getInstance(session.id);
    if (instance) {
      instance.active = active;
      if (active) {
        instance.terminal.focus();
      }
    }
  }, [active, session.id]);

  return (
    <div
      data-testid="terminal-pane-surface"
      className="relative h-full w-full min-h-0 min-w-0 overflow-hidden"
      style={{ backgroundColor: settings.theme.background }}
    >
      <div
        ref={containerRef}
        data-testid="terminal-mount"
        className="relative h-full w-full min-h-0 min-w-0 overflow-hidden"
        style={{ backgroundColor: settings.theme.background }}
      />
      {searchOpen ? (
        <TerminalSearchOverlay
          instance={terminalHostManager.getInstance(session.id)}
          onClose={onCloseSearch ?? (() => undefined)}
        />
      ) : null}
      {error ? (
        <div className="pointer-events-none absolute bottom-3 right-3 max-w-error rounded-md border border-destructive/30 bg-destructive/10 px-2 py-1 text-[11px] text-destructive">
          {error}
        </div>
      ) : null}
    </div>
  );
}

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import {
  createSession,
  flushAnimationFrames,
  mocks,
  setupTerminalHostTestEnv,
} from "./terminalHostManagerTestHelper";
import { terminalEventBus } from "./terminalEvents";
import { MAX_PENDING_OUTPUT_CHARS, terminalHostManager } from "./terminalHostManager";

describe("terminalHostManager output scheduling & batching", () => {
  beforeEach(() => {
    setupTerminalHostTestEnv();
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("unsubscribes previous backendSessionId output subscription when backendSessionId changes in updateSession", async () => {
    const session = createSession("sess-update", "backend-old");
    const unreg = terminalHostManager.registerVisible("sess-update");
    await terminalHostManager.getOrCreate(session, true);

    mocks.terminalWrites.length = 0;
    mocks.emitSessionOutput("backend-old", "hello old");
    flushAnimationFrames();
    expect(mocks.terminalWrites).toContain("hello old");

    mocks.terminalWrites.length = 0;
    const updatedSession = createSession("sess-update", "backend-new");
    terminalHostManager.updateSession("sess-update", updatedSession);

    // Old backend session output must NOT be written anymore
    mocks.emitSessionOutput("backend-old", "old after update");
    flushAnimationFrames();
    expect(mocks.terminalWrites).not.toContain("old after update");

    // New backend session output MUST be written
    mocks.emitSessionOutput("backend-new", "hello new");
    flushAnimationFrames();
    expect(mocks.terminalWrites).toContain("hello new");

    unreg();
    terminalHostManager.destroy("sess-update");
  });

  it("batches same-frame output writes at animation-frame cadence into a single ordered terminal write", async () => {
    const session = createSession("sess-batched", "backend-batch");
    const unreg = terminalHostManager.registerVisible("sess-batched");
    await terminalHostManager.getOrCreate(session, true);

    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-batch", "chunk1-");
    mocks.emitSessionOutput("backend-batch", "chunk2-");
    mocks.emitSessionOutput("backend-batch", "chunk3");

    // Zero immediate writes before frame flush
    expect(mocks.terminalWrites).toHaveLength(0);

    // Flush animation frame
    flushAnimationFrames();

    // Exactly one write call with all 3 chunks in original order
    expect(mocks.terminalWrites).toEqual(["chunk1-chunk2-chunk3"]);

    unreg();
    terminalHostManager.destroy("sess-batched");
  });

  it("cancels pending batched output and prevents writes after destroy or updateSession rebinding", async () => {
    // 1. Teardown via destroy
    const session1 = createSession("sess-teardown-1", "backend-td-1");
    const unreg1 = terminalHostManager.registerVisible("sess-teardown-1");
    await terminalHostManager.getOrCreate(session1, true);
    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-td-1", "pending before destroy");
    unreg1();
    terminalHostManager.destroy("sess-teardown-1");

    flushAnimationFrames();
    expect(mocks.terminalWrites).toHaveLength(0);

    // 2. Teardown via updateSession rebinding
    const session2 = createSession("sess-teardown-2", "backend-td-old");
    const unreg2 = terminalHostManager.registerVisible("sess-teardown-2");
    await terminalHostManager.getOrCreate(session2, true);
    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-td-old", "pending before rebind");
    const session2Updated = createSession("sess-teardown-2", "backend-td-new");
    terminalHostManager.updateSession("sess-teardown-2", session2Updated);

    flushAnimationFrames();
    expect(mocks.terminalWrites).toHaveLength(0);

    // New backend emits and flushes normally
    mocks.emitSessionOutput("backend-td-new", "live new");
    expect(mocks.terminalWrites).toHaveLength(0);
    flushAnimationFrames();
    expect(mocks.terminalWrites).toEqual(["live new"]);

    unreg2();
    terminalHostManager.destroy("sess-teardown-2");
  });

  it("batches outputs per session independently without cross-session mixing", async () => {
    const session1 = createSession("sess-mix-1", "backend-mix-1");
    const session2 = createSession("sess-mix-2", "backend-mix-2");

    const unreg1 = terminalHostManager.registerVisible("sess-mix-1");
    const unreg2 = terminalHostManager.registerVisible("sess-mix-2");

    await terminalHostManager.getOrCreate(session1, true);
    await terminalHostManager.getOrCreate(session2, true);

    mocks.terminalWrites.length = 0;

    mocks.emitSessionOutput("backend-mix-1", "s1-a");
    mocks.emitSessionOutput("backend-mix-2", "s2-a");
    mocks.emitSessionOutput("backend-mix-1", "s1-b");
    mocks.emitSessionOutput("backend-mix-2", "s2-b");

    expect(mocks.terminalWrites).toHaveLength(0);

    flushAnimationFrames();

    expect(mocks.terminalWrites).toEqual(["s1-as1-b", "s2-as2-b"]);

    unreg1();
    unreg2();
    terminalHostManager.destroy("sess-mix-1");
    terminalHostManager.destroy("sess-mix-2");
  });

  it("maintains replay-before-live ordering on initial subscription", async () => {
    const session = createSession("sess-replay", "backend-replay");
    const unreg = terminalHostManager.registerVisible("sess-replay");

    // Simulate backlog replay synchronously during subscribeOutput
    vi.spyOn(terminalEventBus, "subscribeOutput").mockImplementationOnce((sessionId: string, cb: (text: string) => void) => {
      let set = mocks.outputListeners.get(sessionId);
      if (!set) {
        set = new Set();
        mocks.outputListeners.set(sessionId, set);
      }
      set.add(cb);
      cb("replay-chunk-");
      return vi.fn(() => {
        set?.delete(cb);
        if (set?.size === 0) mocks.outputListeners.delete(sessionId);
      });
    });

    await terminalHostManager.getOrCreate(session, true);
    mocks.emitSessionOutput("backend-replay", "live-chunk");

    // Clear preview banner writes
    mocks.terminalWrites.length = 0;

    // Zero immediate writes before frame flush
    expect(mocks.terminalWrites).toHaveLength(0);

    flushAnimationFrames();
    expect(mocks.terminalWrites).toEqual(["replay-chunk-live-chunk"]);

    unreg();
    terminalHostManager.destroy("sess-replay");
  });

  it("synchronously flushes pending output when accumulated characters reach or exceed MAX_PENDING_OUTPUT_CHARS before rAF", async () => {
    const session = createSession("sess-cap", "backend-cap");
    const unreg = terminalHostManager.registerVisible("sess-cap");
    await terminalHostManager.getOrCreate(session, true);

    mocks.terminalWrites.length = 0;

    const halfCap = "A".repeat(MAX_PENDING_OUTPUT_CHARS / 2);
    const exceedCap = "B".repeat(MAX_PENDING_OUTPUT_CHARS / 2 + 10);
    const trailingChunk = "C".repeat(50);

    // 1. Below cap: queued without immediate write
    mocks.emitSessionOutput("backend-cap", halfCap);
    expect(mocks.terminalWrites).toHaveLength(0);

    // 2. Reaching/exceeding cap: synchronously flushes accumulated batch immediately before rAF
    mocks.emitSessionOutput("backend-cap", exceedCap);
    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap]);

    // 3. New chunk arriving after flush is held for next rAF
    mocks.emitSessionOutput("backend-cap", trailingChunk);
    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap]);

    // 4. On rAF flush, trailing chunk is written in ordered sequence
    flushAnimationFrames();
    expect(mocks.terminalWrites).toEqual([halfCap + exceedCap, trailingChunk]);

    unreg();
    terminalHostManager.destroy("sess-cap");
  });
});

