import type { TerminalLifecyclePayload, TerminalOutputPayload } from "./types";
import { onTerminalLifecycle, onTerminalOutput } from "./tauri";
import { TerminalOutputDecoderRegistry } from "./terminalOutput";

const MAX_BACKLOG_CHARS = 512 * 1024;
const MAX_OSC_TITLE_CHARS = 8 * 1024;
const OSC_TITLE_START_RE = /\u001b\](?:0|1|2);/g;
const OSC_PARTIAL_PREFIXES = ["\u001b", "\u001b]", "\u001b]0", "\u001b]1", "\u001b]2"] as const;

type OutputListener = (text: string) => void;
type LifecycleListener = (payload: TerminalLifecyclePayload) => void;
type TitleListener = (sessionId: string, title: string) => void;

type SessionBacklog = {
  chunks: string[];
  totalChars: number;
};

export type OscTitleScanResult = {
  titles: string[];
  carry: string;
};

/**
 * Extracts OSC 0/1/2 terminal titles from decoded PTY output while preserving an incomplete
 * sequence for the next chunk. This runs independently of xterm, so background/unmounted tabs
 * still produce activity title updates.
 */
export function scanTerminalOscTitles(text: string, carry = ""): OscTitleScanResult {
  const source = `${carry}${text}`;
  const titles: string[] = [];
  let searchFrom = 0;

  OSC_TITLE_START_RE.lastIndex = 0;
  while (true) {
    OSC_TITLE_START_RE.lastIndex = searchFrom;
    const match = OSC_TITLE_START_RE.exec(source);
    if (!match) break;

    const valueStart = match.index + match[0].length;
    const terminator = findOscTerminator(source, valueStart);
    if (!terminator) {
      return {
        titles,
        carry: source.slice(Math.max(match.index, source.length - MAX_OSC_TITLE_CHARS)),
      };
    }

    titles.push(source.slice(valueStart, terminator.index));
    searchFrom = terminator.index + terminator.length;
  }

  return { titles, carry: findPartialOscPrefix(source.slice(searchFrom)) };
}

function findOscTerminator(source: string, from: number): { index: number; length: number } | null {
  const candidates = [
    { index: source.indexOf("\u0007", from), length: 1 },
    { index: source.indexOf("\u001b\\", from), length: 2 },
    { index: source.indexOf("\u009c", from), length: 1 },
  ].filter((candidate) => candidate.index >= 0);
  if (candidates.length === 0) return null;
  return candidates.reduce((earliest, candidate) => candidate.index < earliest.index ? candidate : earliest);
}

function findPartialOscPrefix(source: string): string {
  for (const prefix of [...OSC_PARTIAL_PREFIXES].sort((a, b) => b.length - a.length)) {
    if (source.endsWith(prefix)) return prefix;
  }
  return "";
}

class TerminalEventBus {
  private readonly decoderRegistry = new TerminalOutputDecoderRegistry();
  private readonly outputListeners = new Map<string, Set<OutputListener>>();
  private readonly lifecycleListeners = new Set<LifecycleListener>();
  private readonly titleListeners = new Set<TitleListener>();
  private readonly backlog = new Map<string, SessionBacklog>();
  private readonly titleCarry = new Map<string, string>();
  private readonly lastTitle = new Map<string, string>();
  private startPromise: Promise<void> | null = null;

  ensureStarted(): Promise<void> {
    if (this.startPromise) return this.startPromise;
    this.startPromise = Promise.all([
      onTerminalOutput((payload) => this.handleOutput(payload)),
      onTerminalLifecycle((payload) => this.handleLifecycle(payload)),
    ]).then(() => undefined);
    return this.startPromise;
  }

  subscribeOutput(sessionId: string, listener: OutputListener, replay = true) {
    const listeners = this.outputListeners.get(sessionId) ?? new Set<OutputListener>();
    listeners.add(listener);
    this.outputListeners.set(sessionId, listeners);

    if (replay) {
      const existing = this.backlog.get(sessionId);
      if (existing && existing.totalChars > 0) {
        listener(existing.chunks.join(""));
      }
    }

    return () => {
      const current = this.outputListeners.get(sessionId);
      current?.delete(listener);
      if (current?.size === 0) this.outputListeners.delete(sessionId);
    };
  }

  subscribeLifecycle(listener: LifecycleListener) {
    this.lifecycleListeners.add(listener);
    return () => {
      this.lifecycleListeners.delete(listener);
    };
  }

  subscribeTitle(listener: TitleListener) {
    this.titleListeners.add(listener);
    return () => {
      this.titleListeners.delete(listener);
    };
  }

  clearSession(sessionId: string) {
    this.decoderRegistry.reset(sessionId);
    this.backlog.delete(sessionId);
    this.outputListeners.delete(sessionId);
    this.titleCarry.delete(sessionId);
    this.lastTitle.delete(sessionId);
  }

  getBacklogMetricsForTest(sessionId?: string): { sessions: number; chunks: number; chars: number } {
    if (sessionId) {
      const entry = this.backlog.get(sessionId);
      if (!entry) return { sessions: 0, chunks: 0, chars: 0 };
      return {
        sessions: 1,
        chunks: entry.chunks.length,
        chars: entry.totalChars,
      };
    }
    let totalChunks = 0;
    let totalChars = 0;
    for (const entry of this.backlog.values()) {
      totalChunks += entry.chunks.length;
      totalChars += entry.totalChars;
    }
    return {
      sessions: this.backlog.size,
      chunks: totalChunks,
      chars: totalChars,
    };
  }

  private handleOutput(payload: TerminalOutputPayload) {
    const text = this.decoderRegistry.decode(payload.sessionId, payload.data);
    if (text) this.publishOutput(payload.sessionId, text);
  }

  private handleLifecycle(payload: TerminalLifecyclePayload) {
    if (payload.state === "exited" || payload.state === "failed") {
      const tail = this.decoderRegistry.finish(payload.sessionId);
      if (tail) this.publishOutput(payload.sessionId, tail);
    }
    for (const listener of this.lifecycleListeners) listener(payload);
  }

  private publishOutput(sessionId: string, text: string) {
    const scan = scanTerminalOscTitles(text, this.titleCarry.get(sessionId) ?? "");
    if (scan.carry) this.titleCarry.set(sessionId, scan.carry);
    else this.titleCarry.delete(sessionId);

    for (const title of scan.titles) {
      if (this.lastTitle.get(sessionId) === title) continue;
      this.lastTitle.set(sessionId, title);
      for (const listener of this.titleListeners) listener(sessionId, title);
    }

    if (text.length > 0) {
      let entry = this.backlog.get(sessionId);
      if (!entry) {
        entry = { chunks: [], totalChars: 0 };
        this.backlog.set(sessionId, entry);
      }

      entry.chunks.push(text);
      entry.totalChars += text.length;

      while (entry.totalChars > MAX_BACKLOG_CHARS && entry.chunks.length > 0) {
        const oldest = entry.chunks[0];
        if (oldest === undefined) break;
        const overflow = entry.totalChars - MAX_BACKLOG_CHARS;
        if (oldest.length <= overflow) {
          entry.chunks.shift();
          entry.totalChars -= oldest.length;
        } else {
          entry.chunks[0] = oldest.slice(overflow);
          entry.totalChars -= overflow;
          break;
        }
      }
    }

    for (const listener of this.outputListeners.get(sessionId) ?? []) listener(text);
  }
}

export const terminalEventBus = new TerminalEventBus();

export function getBacklogMetricsForTest(sessionId?: string) {
  return terminalEventBus.getBacklogMetricsForTest(sessionId);
}

export function ensureTerminalEvents() {
  return terminalEventBus.ensureStarted();
}

import type { FitAddon } from "@xterm/addon-fit";
import type { Terminal } from "@xterm/xterm";
import React, { useEffect, useRef, useState } from "react";
import { MobileKeyDock } from "../components/MobileKeyDock";
import { attachWebglRenderer, loadTerminalAssets } from "../lib/terminalRenderer";
import { applyTerminalSettings, useTerminalSettings } from "../lib/terminalSettings";

type RemoteTerminalProps = {
  sessionId: string;
  token: string;
  title?: string;
  onBack: () => void;
};

export const RemoteTerminal: React.FC<RemoteTerminalProps> = ({
  sessionId,
  token,
  title,
  onBack,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const rootRef = useRef<HTMLDivElement>(null);
  const wsRef = useRef<WebSocket | null>(null);
  const termRef = useRef<Terminal | null>(null);
  const fitRef = useRef<FitAddon | null>(null);
  const [connected, setConnected] = useState(false);
  const { settings, refreshNativePreferences } = useTerminalSettings();
  const settingsRef = useRef(settings);

  settingsRef.current = settings;

  useEffect(() => {
    void refreshNativePreferences();
  }, [refreshNativePreferences]);

  useEffect(() => {
    if (!containerRef.current) return;

    let terminalInstance: Terminal | null = null;
    let cleanupWebgl: (() => void) | null = null;
    let onDataDisposable: { dispose: () => void } | null = null;
    let isDisposed = false;
    const abortController = new AbortController();

    loadTerminalAssets()
      .then(async ({ Terminal: TerminalCtor, FitAddon: FitAddonCtor }) => {
        if (isDisposed || !containerRef.current) return;

        const term = new TerminalCtor({
          cursorBlink: true,
          fontFamily: settingsRef.current.fontFamily,
          fontSize: settingsRef.current.fontSize,
          macOptionIsMeta: settingsRef.current.macosOptionAsAlt,
          scrollback: settingsRef.current.scrollback,
          cursorStyle: settingsRef.current.cursorStyle,
          allowProposedApi: false,
          customGlyphs: true,
          convertEol: true,
          lineHeight: 1.0,
          letterSpacing: 0,
          theme: {
            background: settingsRef.current.theme.background,
            foreground: settingsRef.current.theme.foreground,
            cursor: settingsRef.current.theme.cursor,
            cursorAccent: settingsRef.current.theme.cursorAccent,
            selectionBackground: settingsRef.current.theme.selectionBackground,
            selectionForeground: settingsRef.current.theme.selectionForeground,
            black: settingsRef.current.theme.black,
            red: settingsRef.current.theme.red,
            green: settingsRef.current.theme.green,
            yellow: settingsRef.current.theme.yellow,
            blue: settingsRef.current.theme.blue,
            magenta: settingsRef.current.theme.magenta,
            cyan: settingsRef.current.theme.cyan,
            white: settingsRef.current.theme.white,
            brightBlack: settingsRef.current.theme.brightBlack,
            brightRed: settingsRef.current.theme.brightRed,
            brightGreen: settingsRef.current.theme.brightGreen,
            brightYellow: settingsRef.current.theme.brightYellow,
            brightBlue: settingsRef.current.theme.brightBlue,
            brightMagenta: settingsRef.current.theme.brightMagenta,
            brightCyan: settingsRef.current.theme.brightCyan,
            brightWhite: settingsRef.current.theme.brightWhite,
            extendedAnsi: settingsRef.current.theme.extendedAnsi,
          },
          allowTransparency: true,
        });

        const fitAddon = new FitAddonCtor();
        term.loadAddon(fitAddon);
        term.open(containerRef.current);
        cleanupWebgl = await attachWebglRenderer(term, abortController.signal);

        if (isDisposed) {
          term.dispose();
          cleanupWebgl?.();
          return;
        }

        // Defer initial fit to requestAnimationFrame with dimension guard
        requestAnimationFrame(() => {
          if (containerRef.current && containerRef.current.clientWidth > 0) {
            fitAddon.fit();
          }
        });

        termRef.current = term;
        fitRef.current = fitAddon;
        terminalInstance = term;

        const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
        const wsUrl = `${protocol}//${window.location.host}/api/v1/terminal/${sessionId}?token=${encodeURIComponent(token)}`;

        const ws = new WebSocket(wsUrl);
        ws.binaryType = "arraybuffer";
        wsRef.current = ws;

        ws.onopen = () => {
          setConnected(true);
          if (containerRef.current && containerRef.current.clientWidth > 0) {
            fitAddon.fit();
            ws.send(JSON.stringify({ type: "resize", cols: term.cols, rows: term.rows }));
          }
        };

        ws.onclose = () => {
          setConnected(false);
        };

        ws.onmessage = (event) => {
          if (typeof event.data === "string") {
            term.write(event.data);
          } else {
            term.write(new Uint8Array(event.data));
          }
        };

        onDataDisposable = term.onData((data) => {
          if (ws.readyState === WebSocket.OPEN) {
            ws.send(new TextEncoder().encode(data));
          }
        });
      })
      .catch(() => {});

    // Coalesced viewport adaptation using requestAnimationFrame
    let rAfId: number | null = null;
    const scheduleResize = () => {
      if (rAfId !== null) cancelAnimationFrame(rAfId);
      rAfId = requestAnimationFrame(() => {
        rAfId = null;
        if (window.visualViewport && rootRef.current) {
          rootRef.current.style.height = `${window.visualViewport.height}px`;
        }
        if (fitRef.current && containerRef.current && containerRef.current.clientWidth > 0 && termRef.current) {
          fitRef.current.fit();
          if (wsRef.current?.readyState === WebSocket.OPEN) {
            wsRef.current.send(
              JSON.stringify({
                type: "resize",
                cols: termRef.current.cols,
                rows: termRef.current.rows,
              })
            );
          }
        }
      });
    };

    window.addEventListener("resize", scheduleResize);
    if (window.visualViewport) {
      window.visualViewport.addEventListener("resize", scheduleResize);
    }

    return () => {
      isDisposed = true;
      abortController.abort();
      if (rAfId !== null) cancelAnimationFrame(rAfId);
      window.removeEventListener("resize", scheduleResize);
      if (window.visualViewport) {
        window.visualViewport.removeEventListener("resize", scheduleResize);
      }
      if (onDataDisposable) {
        onDataDisposable.dispose();
      }
      if (wsRef.current) {
        wsRef.current.close();
      }
      if (cleanupWebgl) {
        cleanupWebgl();
      }
      if (terminalInstance) {
        terminalInstance.dispose();
      }
    };
  }, [sessionId, token]);

  // Synchronize settings changes dynamically
  useEffect(() => {
    if (termRef.current) {
      applyTerminalSettings(termRef.current, settings);
      fitRef.current?.fit();
    }
  }, [settings]);

  const sendKey = (key: string) => {
    const ws = wsRef.current;
    if (!ws || ws.readyState !== WebSocket.OPEN) return;

    const enc = new TextEncoder();
    if (key === "ctrl-c") {
      ws.send(JSON.stringify({ type: "signal", signal: "interrupt" }));
    } else if (key === "tab") {
      ws.send(enc.encode("\t"));
    } else if (key === "esc") {
      ws.send(enc.encode("\x1b"));
    } else if (key === "up") {
      ws.send(enc.encode("\x1b[A"));
    } else if (key === "down") {
      ws.send(enc.encode("\x1b[B"));
    } else if (key === "left") {
      ws.send(enc.encode("\x1b[D"));
    } else if (key === "right") {
      ws.send(enc.encode("\x1b[C"));
    } else if (key === "ctrl-d") {
      ws.send(enc.encode("\x04"));
    } else if (key === "ctrl-z") {
      ws.send(enc.encode("\x1a"));
    } else if (key === "pageup") {
      ws.send(enc.encode("\x1b[5~"));
    } else if (key === "pagedown") {
      ws.send(enc.encode("\x1b[6~"));
    } else if (key === "home") {
      ws.send(enc.encode("\x1b[H"));
    } else if (key === "end") {
      ws.send(enc.encode("\x1b[F"));
    } else if (key.startsWith("alt-")) {
      const char = key.replace("alt-", "");
      ws.send(enc.encode("\x1b" + char));
    } else if (key.startsWith("ctrl-")) {
      const char = key.replace("ctrl-", "");
      if (char.length === 1) {
        const code = char.toUpperCase().charCodeAt(0) - 64;
        if (code >= 1 && code <= 26) {
          ws.send(new Uint8Array([code]));
        }
      }
    } else {
      ws.send(enc.encode(key));
    }
  };

  return (
    <div ref={rootRef} className="flex flex-col h-[100dvh] bg-terminal text-foreground overflow-hidden">
      {/* High-polish Orca Topbar */}
      <div className="flex justify-between items-center px-3 py-1.5 bg-card border-b border-border shrink-0">
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={onBack}
            className="text-xs px-2 py-1 bg-secondary hover:bg-secondary/80 text-secondary-foreground border border-border rounded font-medium transition-colors"
          >
            ← Workspace
          </button>
          <span className="font-medium text-xs text-foreground truncate max-w-[180px]">
            {title || `Terminal (${sessionId.substring(0, 8)})`}
          </span>
        </div>
        <div className="flex items-center gap-1.5">
          <span
            className={`w-2 h-2 rounded-full ${
              connected ? "bg-status-success ring-2 ring-status-success/25" : "animate-pulse bg-status-warning"
            }`}
          />
          <span className="text-[10px] font-mono text-muted-foreground">
            {connected ? "Live" : "Connecting"}
          </span>
        </div>
      </div>

      {/* xterm.js Terminal Container */}
      <div ref={containerRef} className="flex-1 p-1 bg-terminal overflow-hidden" />

      {/* Touch-First Mobile KeyDock */}
      <MobileKeyDock onSendKey={sendKey} />
    </div>
  );
};

> I read this as research/review - inspect the terminal host management and replay/fit lifecycle, diagnose the viewport shift bug, and propose the minimal patch design with deterministic test.

## Technical Review: Terminal Replay & FitAddon Viewport Realignment

---

### 1. Root Cause Analysis

When a warm terminal instance is deactivated, its output subscription is cancelled and its DOM element is unmounted. Upon reactivation:
1. `terminalHostManager.markSessionVisible()` (or `getOrCreate`) invokes `inst.terminal.reset()` to wipe the previous buffer and attaches `attachScheduledOutputSubscription()`.
2. Synchronous backlog output from `terminalEventBus` is enqueued and written via `terminalOutputScheduler`.
3. Concurrently, `TerminalPane` mounts `instance.element` back into the DOM container and triggers `FitAddon.fit()` via the `ResizeObserver` rAF callback or `document.fonts.ready`.
4. During `fitAddon.fit()` (which invokes xterm's internal `terminal.resize(cols, rows)`), xterm reflows lines in the buffer. In xterm.js, reflowing lines across row/column changes when content is at the bottom can calculate a viewport position where `terminal.buffer.active.viewportY === terminal.buffer.active.baseY - 1`.
5. This 1-row disparity leaves the viewport shifted up by one row, clipping the active prompt line and showing an unnecessary 1-row scrollbar.

#### Invariants to Satisfy
- **(a) Realign reset/replayed terminal**: A reactivated terminal has `viewportY === baseY` (0 before write, or at the bottom of the replayed backlog). Fitting must ensure `scrollToBottom()` restores alignment.
- **(b) No forced scroll during live output or user scrollback**: When a user deliberately scrolls up into scrollback (`viewportY < baseY`), neither subsequent live PTY output chunks in `terminalOutputScheduler` nor window/pane resizes via `FitAddon` may call `scrollToBottom()`.
- **(c) Preserves LRU & Inactive replay**: Eviction budgets, refcounts, and backlog-before-live ordering in `terminalHostManager` must remain unchanged.

---

### 2. Concrete Patch Design

The smallest correct fix introduces a unified viewport-aware fit helper `fitTerminalInstance(terminal, fitAddon)` that checks `isAtBottom` before fitting and restores scroll alignment only when the terminal was at the bottom.

#### Insertion Site 1: `ui/src/lib/terminalInstanceFactory.ts`

Define and export `fitTerminalInstance`, and replace raw `fitAddon.fit()` calls in `resize()`:

```typescript
// --- Export helper at top/mid-level ---
export function fitTerminalInstance(terminal: Terminal, fitAddon: FitAddon): void {
  const isAtBottom =
    (terminal.buffer?.active?.viewportY ?? 0) >= (terminal.buffer?.active?.baseY ?? 0);
  fitAddon.fit();
  if (isAtBottom) {
    terminal.scrollToBottom?.();
  }
}

