// ... inside applyInstanceSettings ...
  applyInstanceSettings(sessionId: string, settings: EffectiveTerminalSettings) {
    const inst = this.instances.get(sessionId);
    if (inst) {
      applyTerminalSettings(inst.terminal, settings);
      if (inst.element.clientWidth > 0 && inst.element.clientHeight > 0) {
        fitTerminalInstance(inst.terminal, inst.fitAddon);
      }
    }
  }

// ... inside applySettings ...
  applySettings(settings: EffectiveTerminalSettings) {
    for (const inst of this.instances.values()) {
      applyTerminalSettings(inst.terminal, settings);
      if (inst.element.clientWidth > 0 && inst.element.clientHeight > 0) {
        fitTerminalInstance(inst.terminal, inst.fitAddon);
      }
    }
  }
```

#### Insertion Site 4: `ui/src/lib/terminalOutputScheduler.ts`

**No changes required.** `terminalOutputScheduler` continues to write batched output via `terminal.write(coalesced)` without forcing `scrollToBottom()`. This guarantees that normal live PTY writes do not snap user-scrolled scrollback to the bottom.

---

### 3. Execution and Lifecycle Ordering

```
[Warm Tab Reactivation]
  │
  ├─ 1. terminalHostManager.registerVisible(sessionId)
  │      └─ markSessionVisible():
  │           ├─ inst.terminal.reset()  ───> buffer: baseY=0, viewportY=0 (isAtBottom=true)
  │           └─ attachScheduledOutputSubscription():
  │                └─ subscribeOutput() delivers backlog chunks
  │
  ├─ 2. terminalOutputScheduler
  │      └─ flushOutput() calls terminal.write(backlog)
  │           └─ Buffer lines populated; xterm tracks viewportY === baseY
  │
  ├─ 3. DOM Mount & Fit (ResizeObserver rAF / fontsReady)
  │      └─ fitTerminalInstance(terminal, fitAddon):
  │           ├─ Evaluates isAtBottom (true for replayed buffer)
  │           ├─ fitAddon.fit() (invokes terminal.resize, may shift viewportY to baseY - 1)
  │           └─ isAtBottom is true ──> terminal.scrollToBottom() restores viewportY = baseY
  │
  └─ 4. User Interaction Phase
         ├─ Normal Live Output: terminal.write() flushes without forced scroll; xterm handles native scroll logic.
         └─ Deliberate Scrollback (viewportY < baseY): subsequent resizes evaluate isAtBottom=false and skip scrollToBottom().
```

