import { fitTerminalInstance } from "./terminalInstanceFactory";
import { terminalScrolledToBottom } from "./terminalHostManagerTestHelper";

it("realigns viewport to bottom after fit when terminal is replayed / at bottom", async () => {
  const session = createSession("sess-realign", "backend-realign");
  const unreg = terminalHostManager.registerVisible("sess-realign");
